import{_ as t,o as r,c as a,ae as i}from"./chunks/framework.vXWZTEWX.js";const m=JSON.parse('{"title":"👁️ Sentry & Observability Policy - TenderCheck AI","description":"","frontmatter":{},"headers":[],"relativePath":"standards/sentry_policy.md","filePath":"standards/sentry_policy.md"}'),n={name:"standards/sentry_policy.md"};function o(s,e,l,c,d,p){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="👁️-sentry-observability-policy-tendercheck-ai" tabindex="-1">👁️ Sentry &amp; Observability Policy - TenderCheck AI <a class="header-anchor" href="#👁️-sentry-observability-policy-tendercheck-ai" aria-label="Permalink to &quot;👁️ Sentry &amp; Observability Policy - TenderCheck AI&quot;">​</a></h1><h2 id="_1-monitoring-objectives" tabindex="-1">1. Monitoring Objectives <a class="header-anchor" href="#_1-monitoring-objectives" aria-label="Permalink to &quot;1. Monitoring Objectives&quot;">​</a></h2><p>[cite_start]To provide real-time visibility into the application&#39;s health, ensuring that every error is captured and every performance bottleneck is identified before it impacts the user.</p><h2 id="_2-error-tracking-implementation" tabindex="-1">2. Error Tracking Implementation <a class="header-anchor" href="#_2-error-tracking-implementation" aria-label="Permalink to &quot;2. Error Tracking Implementation&quot;">​</a></h2><ul><li>[cite_start]<strong>Global Boundary</strong>: Implement Sentry error boundaries in the React frontend to catch rendering crashes.</li><li>[cite_start]<strong>Backend Middleware</strong>: Use Sentry&#39;s request handlers in the Express backend to automatically capture 500-level errors and unhandled promise rejections[cite: 663].</li><li><strong>Contextual Data</strong>: Every captured error must include the <code>user_id</code> (if authenticated) and relevant tags like <code>analysis_id</code> to facilitate debugging.</li></ul><h2 id="_3-performance-core-web-vitals" tabindex="-1">3. Performance &amp; Core Web Vitals <a class="header-anchor" href="#_3-performance-core-web-vitals" aria-label="Permalink to &quot;3. Performance &amp; Core Web Vitals&quot;">​</a></h2><ul><li>[cite_start]<strong>Transaction Tracking</strong>: Monitor the latency of long-running processes, specifically PDF parsing and AI extraction steps.</li><li>[cite_start]<strong>User Perception</strong>: Correlate technical metrics (LCP, FID, CLS) with the &quot;perceived speed&quot; of the application to ensure a smooth UX[cite: 664, 682].</li><li>[cite_start]<strong>Optimistic UI Validation</strong>: Track instances where an &quot;Optimistic UI&quot; update requires a rollback due to a backend failure[cite: 209].</li></ul><h2 id="_4-ai-specific-observability" tabindex="-1">4. AI Specific Observability <a class="header-anchor" href="#_4-ai-specific-observability" aria-label="Permalink to &quot;4. AI Specific Observability&quot;">​</a></h2><ul><li><strong>LLM Telemetry</strong>: Capture breadcrumbs for every AI prompt sent and response received to debug &quot;hallucinations&quot; or timeouts.</li><li><strong>Token Usage &amp; Cost</strong>: (Optional) Use Sentry custom measurements to track token consumption per analysis.</li></ul><h2 id="_5-release-alert-management" tabindex="-1">5. Release &amp; Alert Management <a class="header-anchor" href="#_5-release-alert-management" aria-label="Permalink to &quot;5. Release &amp; Alert Management&quot;">​</a></h2><ul><li><strong>Environment Scoping</strong>: Distinguish between <code>development</code>, <code>staging</code>, and <code>production</code> environments to keep alerts relevant.</li><li>[cite_start]<strong>Intelligent Alerts</strong>: Configure Sentry to trigger alerts only for service degradations or high-frequency errors, avoiding &quot;alert fatigue&quot;[cite: 665].</li><li><strong>Source Maps</strong>: Integrate the CI/CD pipeline to upload source maps, ensuring that production stack traces point to the original TypeScript code.</li></ul>',11)])])}const h=t(n,[["render",o]]);export{m as __pageData,h as default};
